using System.IO;
using System.Linq;
using UnityEditor;
using UnityEngine;
namespace ROM.EditorTools {
public static class LittleDemonMaterials {
 static Texture Texture(Material source,params string[] names){foreach(var name in names)if(source.HasProperty(name)&&source.GetTexture(name))return source.GetTexture(name);var entries=new SerializedObject(source).FindProperty("m_SavedProperties.m_TexEnvs");for(int i=0;i<entries.arraySize;i++){var item=entries.GetArrayElementAtIndex(i);if(names.Contains(item.FindPropertyRelative("first").stringValue)){var texture=item.FindPropertyRelative("second.m_Texture").objectReferenceValue as Texture;if(texture)return texture;}}return null;}
 static Texture2D Read(Texture source,int width,int height,bool linear){var previous=RenderTexture.active;var rt=RenderTexture.GetTemporary(width,height,0,RenderTextureFormat.ARGB32,linear?RenderTextureReadWrite.Linear:RenderTextureReadWrite.sRGB);Graphics.Blit(source,rt);RenderTexture.active=rt;var image=new Texture2D(width,height,TextureFormat.RGBA32,false,linear);image.ReadPixels(new Rect(0,0,width,height),0,0);image.Apply();RenderTexture.active=previous;RenderTexture.ReleaseTemporary(rt);return image;}
 static Texture Alpha(Texture color,Texture opacity,string name,string output){string path=output+"/Materials/"+name+"_RGBA.png";var existing=AssetDatabase.LoadAssetAtPath<Texture2D>(path);if(existing)return existing;int width=Mathf.Min(2048,Mathf.Max(color.width,opacity.width)),height=Mathf.Min(2048,Mathf.Max(color.height,opacity.height));var rgb=Read(color,width,height,false);var mask=Read(opacity,width,height,true);var colors=rgb.GetPixels32();var alpha=mask.GetPixels32();for(int i=0;i<colors.Length;i++)colors[i].a=alpha[i].r;rgb.SetPixels32(colors);rgb.Apply();File.WriteAllBytes(path,rgb.EncodeToPNG());Object.DestroyImmediate(rgb);Object.DestroyImmediate(mask);AssetDatabase.ImportAsset(path,ImportAssetOptions.ForceSynchronousImport);var importer=(TextureImporter)AssetImporter.GetAtPath(path);importer.alphaSource=TextureImporterAlphaSource.FromInput;importer.alphaIsTransparency=true;importer.mipmapEnabled=true;importer.SaveAndReimport();return AssetDatabase.LoadAssetAtPath<Texture2D>(path);}
 static Texture2D White(string output){string path=output+"/Materials/SolidWhite.png";var texture=AssetDatabase.LoadAssetAtPath<Texture2D>(path);if(texture)return texture;texture=new Texture2D(2,2,TextureFormat.RGBA32,false);texture.SetPixels(new[]{Color.white,Color.white,Color.white,Color.white});texture.Apply();File.WriteAllBytes(path,texture.EncodeToPNG());Object.DestroyImmediate(texture);AssetDatabase.ImportAsset(path,ImportAssetOptions.ForceSynchronousImport);return AssetDatabase.LoadAssetAtPath<Texture2D>(path);}
 public static Material Variant(Material source)=>Variant(source,LittleDemonBuilder.Package,LittleDemonBuilder.Root);
 public static Material Variant(Material source,string package,string output){
  string regular=source.name.StartsWith("MS_")?"M_"+source.name.Substring(3):source.name;
  string standard=AssetDatabase.FindAssets(regular+" t:Material",new[]{package}).Select(AssetDatabase.GUIDToAssetPath).FirstOrDefault(p=>Path.GetFileNameWithoutExtension(p)==regular);
  Material converted;
  if(standard!=null&&AssetDatabase.LoadAssetAtPath<Material>(standard).shader.name=="Universal Render Pipeline/Lit")converted=new Material(AssetDatabase.LoadAssetAtPath<Material>(standard));
  else {
   converted=new Material(Shader.Find("Universal Render Pipeline/Lit"));var color=Texture(source,"_Base_Map","_BaseMap","_MainTex");var opacity=Texture(source,"_Opacity_Map");if(!color){color=White(output);if(source.HasProperty("_BaseColor"))converted.SetColor("_BaseColor",source.GetColor("_BaseColor"));}if(color&&opacity)color=Alpha(color,opacity,source.name,output);converted.SetTexture("_BaseMap",color);var normal=Texture(source,"_Normal_Map","_BumpMap");if(normal){converted.SetTexture("_BumpMap",normal);converted.EnableKeyword("_NORMALMAP");}converted.SetFloat("_Smoothness",.25f);if(source.HasProperty("_Color")&&!source.HasProperty("_Base_Color"))converted.SetColor("_BaseColor",source.GetColor("_Color"));
   if(opacity||source.name.Contains("Eyelash")||source.name.Contains("Eyebrow")){converted.SetFloat("_AlphaClip",1);converted.SetFloat("_Cutoff",.4f);converted.SetFloat("_Cull",0);converted.EnableKeyword("_ALPHATEST_ON");converted.SetOverrideTag("RenderType","TransparentCutout");converted.renderQueue=2450;}
  }
  converted.enableInstancing=true;string path=output+"/Materials/"+source.name+".mat";var material=AssetDatabase.LoadAssetAtPath<Material>(path);if(!material){material=converted;AssetDatabase.CreateAsset(material,path);}else{material.shader=converted.shader;material.CopyPropertiesFromMaterial(converted);Object.DestroyImmediate(converted);}EditorUtility.SetDirty(material);if(!material.GetTexture("_BaseMap"))throw new System.Exception("Missing base texture: "+source.name);return material;
 }
 public static void Preview(GameObject prefab,string output="Documentation/little-demon/preview.png"){var preview=new PreviewRenderUtility();try{preview.cameraFieldOfView=30;var instance=Object.Instantiate(prefab);preview.AddSingleGO(instance);instance.GetComponent<UnityEngine.AI.NavMeshAgent>().enabled=false;var animator=instance.GetComponentInChildren<Animator>();var idle=animator.runtimeAnimatorController.animationClips.First(c=>c.name=="Idle01");idle.SampleAnimation(animator.gameObject,.2f);preview.camera.transform.position=new Vector3(1.65f,.95f,2.7f);preview.camera.transform.LookAt(new Vector3(0,.7f,0));var meshBounds=instance.GetComponentsInChildren<Renderer>().First().bounds;foreach(var renderer in instance.GetComponentsInChildren<Renderer>())meshBounds.Encapsulate(renderer.bounds);preview.camera.transform.position=meshBounds.center+new Vector3(1,.25f,1.7f)*Mathf.Max(.5f,meshBounds.size.magnitude)*.9f;preview.camera.transform.LookAt(meshBounds.center);preview.camera.nearClipPlane=.01f;preview.camera.farClipPlane=20;preview.lights[0].intensity=1.3f;preview.lights[0].transform.rotation=Quaternion.Euler(35,210,0);preview.lights[1].intensity=1;preview.ambientColor=new Color(.35f,.35f,.4f);preview.BeginStaticPreview(new Rect(0,0,650,800));preview.Render(true);var image=preview.EndStaticPreview();File.WriteAllBytes(output,image.EncodeToPNG());Object.DestroyImmediate(image);}finally{preview.Cleanup();}}
}
}
